package com.example.sim;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

public class Main {
    public static void main(String[] args) throws Exception {
        String scenario = null;
        String output = null;

        // Accept --scenario <path> --output <path> in any order, also accept -s/-o.
        for (int i = 0; i < args.length; i++) {
            String a = args[i];
            if (a.equals("--scenario") || a.equals("-s")) {
                scenario = args[++i];
            } else if (a.equals("--output") || a.equals("-o")) {
                output = args[++i];
            }
        }
        if (scenario == null || output == null) {
            System.err.println("Usage: --scenario <scenario_path> --output <output_path>");
            System.exit(1);
        }

        HeadlessApplicationConfiguration cfg = new HeadlessApplicationConfiguration();
        cfg.updatesPerSecond = 0; // run as fast as possible
        cfg.idlePriority = Thread.MIN_PRIORITY;

        SimulationListener listener = new SimulationListener(scenario, output);
        HeadlessApplication app = new HeadlessApplication(listener, cfg);

        // Wait for the application thread to finish. The listener calls
        // Gdx.app.exit() once all ticks are processed; the application
        // thread then terminates, releasing this join.
        try {
            // The internal thread that runs create()/render()/dispose()
            // is not exposed, so we poll until Gdx.app no longer exists
            // (after exit it is set to null) and the application thread
            // is no longer alive.
            Thread renderThread = getRenderThread(app);
            if (renderThread != null) {
                renderThread.join();
            }
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
            System.exit(2);
        }
        // Give the listener a moment to flush+close.
        Thread.sleep(50);
    }

